WITH remaining_keys AS (SELECT product_id, store_id FROM inventory EXCEPT SELECT product_id, store_id FROM inventory WHERE quantity <= 231), kept_rows AS (SELECT s.* FROM inventory s INNER JOIN remaining_keys k ON s.product_id = k.product_id AND s.store_id = k.store_id) SELECT s.id, s.product_id, s.last_restock, (SELECT AVG(o2.quantity) FROM order_items o2 WHERE o2.product_id = s.product_id) AS avg_order_item_quantity FROM kept_rows s ORDER BY product_id NULLS FIRST;
